    adj = [[] for _ in range(n + 1)]
    for i, (u, v, w) in enumerate(edges):
        adj[u].append((v, i))
        adj[v].append((u, i))

    # Check if there's a path from s to t avoiding certain edge indices
    def has_path(blocked):
        visited = [False] * (n + 1)
        queue = deque([s])
        visited[s] = True

        while queue:
            u = queue.popleft()
            if u == t:
                return True
            for v, e_idx in adj[u]:
                if not visited[v] and e_idx not in blocked:
                    visited[v] = True
                    queue.append(v)
        return False

    # Try 0 edges removed
    if not has_path(set()):
        return "0\n0\n"

    # Try 1 edge removed
    for e_idx in range(m):
        blocked = {e_idx}
        if not has_path(blocked):
            return "0\n1\n" + str(e_idx + 1)

