def solution(input_data):
    lines = input_data.strip().split('\n')
    n, m = map(int, lines[0].split())

    edges = []
    for i in range(m):
        a, b, e = map(int, lines[i+1].split())
        edges.append((a-1, b-1, e, i))

    # Sort edges by weight for Kruskal's
    s_edges = sorted(edges, key=lambda x: x[2])

    # Union-find for MST
    parent = list(range(n))
    def find(x):
        path = []
        while parent[x] != x:
            path.append(x)
            x = parent[x]
        for node in path:
            parent[node] = x
        return x

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    # Build MST
    mst_edges = []
    for u, v, w, idx in s_edges:
        if union(u, v):
            mst_edges.append((u, v, w, idx))
            if len(mst_edges) == n - 1:
                break

    mst_set = {idx for _, _, _, idx in mst_edges}

    # Build adjacency list for the MST tree
    adj_tree = [[] for _ in range(n)]
    for u, v, w, idx in mst_edges:
        adj_tree[u].append((v, w))
        adj_tree[v].append((u, w))

    # Maximum bits for LOG (up to 10^5, so ~17 bits)
    MAX_LOG = 20

    # Tree preprocessing with iterative DFS
    depth = [0] * n
    parent_0 = [-1] * n
    max_edge_0 = [0] * n

    stack = [(0, -1, 0)]
    dfs_visited = [False] * n
    dfs_visited[0] = True

    while stack:
        u, p, w = stack.pop()
        depth[u] = depth[p] + 1 if p != -1 else 0
        parent_0[u] = p
        max_edge_0[u] = w

        for v, wt in adj_tree[u]:
            if v != p:
                dfs_visited[v] = True
                stack.append((v, u, wt))

    # Build binary lifting table
    parent_lift = [[-1] * n for _ in range(MAX_LOG)]
    max_edge_val = [[0] * n for _ in range(MAX_LOG)]

    for i in range(n):
        parent_lift[0][i] = parent_0[i]
        max_edge_val[0][i] = max_edge_0[i]

    for j in range(1, MAX_LOG):
        for i in range(n):
            if parent_lift[j-1][i] != -1:
                parent_lift[j][i] = parent_lift[j-1][parent_lift[j-1][i]]
                max_edge_val[j][i] = max(max_edge_val[j-1][i], max_edge_val[j-1][parent_lift[j-1][i]])
            else:
                parent_lift[j][i] = -1
                max_edge_val[j][i] = max_edge_val[j-1][i]

    # Query max edge on path between two nodes
    def query_max(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        ret = 0
        diff = depth[u] - depth[v]

        for j in range(MAX_LOG):
            if (diff >> j) & 1:
                ret = max(ret, max_edge_val[j][u])
                u = parent_lift[j][u]

        if u == v:
            return ret

        for j in range(MAX_LOG - 1, -1, -1):
            if parent_lift[j][u] != parent_lift[j][v]:
                ret = max(ret, max_edge_val[j][u])
                ret = max(ret, max_edge_val[j][v])
                u = parent_lift[j][u]
                v = parent_lift[j][v]

        ret = max(ret, max_edge_val[0][u])
        ret = max(ret, max_edge_val[0][v])
        return ret

    # Collect results for all non-MST edges
    results = []
    for u, v, w, idx in edges:
        if idx in mst_set:
            continue
        results.append(str(query_max(u, v)))

    return '\n'.join(results)

