            visited[start] = True
            curr = start

            while True:
                # Find next node in chain
                next_node = -1
                for nxt in adj[curr]:
                    if not visited[nxt]:
                        next_node = nxt
                        break

                if next_node == -1:
                    break

                visited[next_node] = True
                chain.append(next_node)
                curr = next_node

            chains.append(chain)

    # Check if each special pair is satisfied in the same chain
    # Special pairs define immediate succession within chains
    pair_in_chain = set()
    for chain in chains:
        for i in range(len(chain) - 1):
            pair_in_chain.add((chain[i], chain[i+1]))

    # Verify all special pairs are satisfied
    for x, y in special_pairs:
        if (x, y) not in pair_in_chain:
