            prev_node = chain[idx-1]
            curr_node = chain[idx]
            parent_curr = parent[curr_node]
            if parent_curr == prev_node:
                in_degree[curr_node] += 1

    # Topological sort to find valid ordering of chains
    # Treat each chain as a unit
