    for chain in chains:
        for node in chain:
            node_set.add(node)

    # Cherry-pick: build target ordering
    target_ordering = []
    for chain in chains:
        target_ordering.extend(chain)

    # Verify the target ordering satisfies all prerequisites
    pos = {node: i for i, node in enumerate(target_ordering)}

    for i in range(1, n + 1):
