        p[i] = float(b) / (a + b)

    # Store initial probabilities for updates
    p_list = list(p[:])  # Copy to list for updates

    # Build a formula for P(l→r)
    # Given non-decreasing p values, use the product formula
    # P(l→r) = prod of p[i]/(1-p[i-1]) for i in range(l, r+1) with adjustments

    output_lines = []

    def compute_dominate(l, r):
        """
        Probability of dominating on interval l...r
        Start at l, never lose at l, finish by winning at r
        """
        if l == r:
            return p[l]  # Just probability to win at l

        # For domination: start at l, win at l (prob p[l]), 
        # then reach r before falling out, and win at r
        # With non-decreasing p, we use a product-based formula

        # The key insight: P(dominates) = p[l] * (something involving all p)
        # For a proper solution, we need to solve the random walk equations

        # P(k→k) = p[k] (just win at k)
        # For l < r, we need to compute the probability

        # Using standard random walk theory:
        # Let Q(k) = probability of reaching r before l-1 starting from k
        # Q(l+1) is key

        prod = 1.0
        sum_st = 0.0
        sum_curr = 0.0

        for i in range(l, r):
            ratio = p[i] / (1.0 - p[i] + 1e-15) if p[i] != 1.0 else float('inf')
            sum_st += ratio
            sum_curr += ratio * pow(ratio, (i - l))

        if l == r:
            return p[l]

        # The probability involves geometric series with ratio r[i] = p[i]/(1-p[i])
        # P = p[l] * (1 / (1 + sum of certain ratios))

        denom = 1.0 + sum_st
        return p[l] / denom

    # For the actual probabilistic solution with non-decreasing p:
    # Q(k) = (prod_{j=k}^{r-1} r[j] - prod_{j=l}^{k-1} r[j]) / 
    #       (prod_{j=l}^{r-1} r[j] - 1)
    # where r[j] = p[j]/(1-p[j])

    def prob_dominate(l, r):
        if l == r:
            return p[l]

        # Compute ratios r[i] = p[i]/(1-p[i])
        ratios = []
        for i in range(l, r):
            if p[i] >= 0.999999999:  # Handle edge case near 1
                ratios.append(1e18)
            else:
                ratios.append(p[i] / (1.0 - p[i]))

        # P_reach = probability of reaching r before l-1 from l+1
        # = (prod_{i=l}^{r-1} r[i] - 1) / (prod_{i=l}^{r-1} r[i]) if we consider starting from l+1

        if l + 1 > r:
            return p[l]

        prod = 1.0
        for i in range(l, r):
            prod *= ratios[i]

        if abs(prod - 1.0) < 1e-12:
            # Special case: all ratios ~ 1
            return p[l] * (1.0 + (p[l+1] - 0.5) * 10.0)  # Approximation

        return p[l] * (1.0 - 1.0 / prod)

    # Process queries
    query_idx = n + 1
    query_lines = lines[query_idx:]

    for ql in query_lines:
