        if parts[0] == '1':
            # Update: 1 i a b
            i = int(parts[1])
            a = int(parts[2])
            b = int(parts[3])
            p[i] = float(b) / (a + b)
            p_list[i-1] = float(b) / (a + b)
        else:
            # Query: 2 l r
            l, r = int(parts[1]), int(parts[2])

            if l == r:
                ans = p[l]
            else:
                # For non-decreasing p sequence, use formula:
                # P = p[l] + p[l]*(1-p[l]) * (1-p[l]) + ... 
                # Actually compute properly:

                # This is a geometric series solution
                prod_r = 1.0
                for i in range(l, r):
                    if p[i] >= 1.0 - 1e-12:
                        prod_r = float('inf')
                        break
                    prod_r *= p[i] / (1.0 - p[i])

