def is_geometric(seq):
    """Check if a sequence is a geometric progression."""
    k = len(seq)
    if k <= 2:
        return True

    x0, x1 = seq[0], seq[1]

    # If first element is 0, all must be 0
    if x0 == 0:
        return all(x == 0 for x in seq)

    # If second element is 0 (and first is not), ratio is 0
    if x1 == 0:
        return all(x == 0 for x in seq[2:])

    # Use cross-multiplication: x0 * seq[i] == x1 * seq[i-1]
    # This avoids floating point issues
    for i in range(2, k):
        if x0 * seq[i] != x1 * seq[i-1]:
            return False

    return True


