def get_sorted_table(table, col_indices):
    """Stably sort table by the given column indices in order"""
    result = [tuple(row) for row in table]
    for col_idx in reversed(col_indices):
        # Sort by the column, maintaining stability
        indexed = list(enumerate(result, 1))
        indexed.sort(key=lambda x: x[1][col_idx])
        result = [x[1] for x in indexed]
    return [list(row) for row in result]

