    s1 = lines[0].strip()
    s2 = lines[1].strip()
    virus = lines[2].strip()

    # Handle empty virus case (any LCS is valid)
    if not virus:
        m, n = len(s1), len(s2)
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if s1[i-1] == s2[j-1]:
                    dp[i][j] = dp[i-1][j-1] + 1
                else:
                    dp[i][j] = max(dp[i-1][j], dp[i][j-1])

        res = []
        i, j = m, n
        while i > 0 and j > 0:
            if s1[i-1] == s2[j-1] and dp[i][j] == dp[i-1][j-1] + 1:
                res.append(s1[i-1])
                i -= 1
                j -= 1
            elif dp[i][j] == dp[i-1][j]:
                i -= 1
            else:
                j -= 1
        return ''.join(res) if res else '0'

    # Handle edge case where empty string is the only valid answer
    if not s1 or not s2:
        return '0'

    # Build KMP failure function for virus
    n_virus = len(virus)
    pi = [0] * n_virus
    for i in range(1, n_virus):
        j = pi[i-1]
        while j > 0 and virus[i] != virus[j]:
            j = pi[j-1]
        if virus[i] == virus[j]:
            j += 1
        pi[i] = j

    def get_next_state(k, char):
        """KMP transition: state k -> new state after reading char"""
        while k > 0 and virus[k] != char:
            k = pi[k-1]
        if virus[k] == char:
            k += 1
        return k

    m, n = len(s1), len(s2)

    # dp[i][j][k] = max length of valid LCS using s1[:i], s2[:j], with KMP state k
    # A state k is valid if k < n_virus (i.e., virus not yet completed as substring)
    dp = [[[-1] * n_virus for _ in range(n + 1)] for _ in range(m + 1)]
    parent = [[[None] * n_virus for _ in range(n + 1)] for _ in range(m + 1)]

    # Base case
    dp[0][0][0] = 0

    for i in range(m + 1):
        for j in range(n + 1):
            for k in range(n_virus):
                if dp[i][j][k] == -1:
                    continue

                # Option 1: Skip s1[i-1] (advance i, keep j, same k)
                if i < m:
                    nk = get_next_state(k, s1[i])
                    if nk < n_virus:
                        new_len = dp[i][j][k]
                        if new_len > dp[i+1][j][nk]:
                            dp[i+1][j][nk] = new_len
                            parent[i+1][j][nk] = (i, j, k, None)

                # Option 2: Skip s2[j-1] (keep i, advance j, same k)
                if j < n:
                    nk = get_next_state(k, s2[j])
                    if nk < n_virus:
                        new_len = dp[i][j][k]
                        if new_len > dp[i][j+1][nk]:
                            dp[i][j+1][nk] = new_len
                            parent[i][j+1][nk] = (i, j, k, None)

                # Option 3: Match s1[i-1] with s2[j-1] (advance both)
                if i > 0 and j > 0 and s1[i-1] == s2[j-1]:
                    nk = get_next_state(k, s1[i-1])
                    if nk < n_virus:  # Valid match
                        new_len = dp[i-1][j-1][k] + 1
                        if new_len > dp[i][j][nk]:
                            dp[i][j][nk] = new_len
                            parent[i][j][nk] = (i-1, j-1, k, s1[i-1])

    # Find maximum length among all valid end states
    max_len = -1
    best_k = -1
    for k in range(n_virus):
        if dp[m][n][k] > max_len:
            max_len = dp[m][n][k]
            best_k = k

    if max_len < 0 or max_len == 0:
        return '0'

    # Reconstruct solution using parent pointers
    res = []
    i, j, k = m, n, best_k
    while (i, j, k) != (0, 0, 0):
        p = parent[i][j][k]
        if p is None:
            break
        prev_i, prev_j, prev_k, char = p
        if char is not None:
            res.append(char)
        i, j, k = prev_i, prev_j, prev_k

    if res:
        return ''.join(reversed(res))
    else:
        return '0'

