def solution(s):
    lines = s.strip().split('\n')
    if not lines:
        return "Impossible"

    n, m = map(int, lines[0].split())

    edges = []
    for i in range(m):
        a, b = map(int, lines[1 + i].split())
        # Normalize so a < b for easier comparison
        if a > b:
            a, b = b, a
        edges.append((a, b, i))

    def cross(i, j):
        """Check if two edges cross geometrically"""
        (a1, b1) = edges[i][:2]
        (a2, b2) = edges[j][:2]

        # Same endpoints or reversed don't count as crossing
        if a1 == a2 and b1 == b2:
            return False

        def between(x, y, z):
            """Check if point z is uniquely between x and y on the cycle"""
            if x < y:
                return x < z < y
            else:
                return z < x or y < z

        a2_between = between(a1, b1, a2)
        b2_between = between(a1, b1, b2)
        # They cross if one endpoint is between, and the other is not
        return a2_between != b2_between

    # Build conflict graph - edge between roads if they cross
    adj = [[] for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            if cross(i, j):
                adj[i].append(j)
                adj[j].append(i)

    # Try to 2-color the conflict graph (check if bipartite)
    colors = [-1] * m
    possible = True

    for i in range(m):
        if colors[i] == -1:
            # BFS to color component
            queue = [i]
            colors[i] = 0
            while queue and not possible:
                u = queue.pop(0)
                for v in adj[u]:
                    if colors[v] == -1:
                        colors[v] = 1 - colors[u]
                        queue.append(v)
                    elif colors[v] == colors[u]:
                        # Both endpoints have same color - not bipartite
                        possible = False
                        break

    if possible:
        # Output 'i' for color 0, 'o' for color 1
        return ''.join('i' if colors[i] == 0 else 'o' for i in range(m))
    else:
        return "Impossible"

from functools import lru_cache

def solution(input_str):
    parts = input_str.strip().split()
    if not parts:
        return "Missing\n"
    a = int(parts[0])
    b = int(parts[1])
    n = int(parts[2])

    @lru_cache(maxsize=None)
    def can_win(av, bv):
        if av ** bv >= n:
            return False
        return (can_win(av + 1, bv) or can_win(av, bv + 1))

    return "Stas\n" if can_win(a, b) else "Masha\n"

# Test on sample cases
print(solution('3 1 4\n'))
print(solution('2 2 10\n'))
print(solution('5 5 16808\n'))
print(solution('1 4 10\n'))

