    n = int(tokens[1])
    chairs = [int(tokens[i + 2]) for i in range(n)]

    chairs = sorted(chairs)

    if m == n:
        return "0"

    max_gap = 0
    for i in range(n):
        curr = chairs[i]
        next_pos = chairs[(i + 1) % n]
        if i < n - 1:
            gap = next_pos - curr - 1
        else:
            # Wrap around from last chair to first chair
            gap = m - chairs[-1] + chairs[0] - 1
        max_gap = max(max_gap, gap)

    return str((max_gap + 1) // 2)

