def solution(input_string):
    n, k = map(int, input_string.split())

    if n == 1:
        if k == 1:
            return "0\n"
        return "-1\n"

    # For small n, compute directly by enumerating
    # For large n (n > 20), use the pattern formula
    # The count of representatives for n strings follows 2^(n-1)

    if n <= 20:
        def get_min_in_class(s):
            variants = {s, s[::-1]}
            swapped = ''.join('1' if c == '0' else '0' for c in s)
            variants.add(swapped)
            variants.add(swapped[::-1])
            return min(variants)

        representatives = set()
        for i in range(1 << n):
            s = bin(i)[2:].zfill(n)
            min_s = get_min_in_class(s)
            representatives.add(min_s)

        representatives = sorted(list(representatives))
        if k <= len(representatives):
            return representatives[k-1] + '\n'
        else:
            return "-1\n"
    else:
        # For n > 20, use formula
        # Number of representatives = 2^(n-1)
        # k-th representative follows Gray code pattern for strings starting with '0'
        count = 1 << (n - 1)

        if k > count:
            return "-1\n"

        # Generate k-th representative using Gray code ordering
        # Pattern for n > 20: first n-2 positions are '0', then alternate
        result = ['0'] * n

        # Position n-2 and n-1 encode the index k in Gray code
        gray_index = k - 1

        for i in range(n - 2):
            result[i] = '0'

        result[n - 2] = str((gray_index >> 0) & 1)
        result[n - 1] = str((gray_index >> 1) & 1)

        return ''.join(result) + '\n'

