        # Build adjacency: wire i connects to wire j if they share an endpoint
        adj = defaultdict(set)
        for i in range(n):
            x, y, w = wires[i]
            for j in range(n):
                if i == j:
                    continue
                nx, ny, _ = wires[j]
                if x == nx or x == ny or y == nx or y == ny:
                    adj[i].add(j)

        # Find connected components
        visited = [False] * n
        components = []
        comp_count = 0

        for i in range(n):
            if not visited[i]:
                comp = []
                stack = [i]
                visited[i] = True
                while stack:
                    node = stack.pop()
                    comp.append(node)
                    for neighbor in adj[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            stack.append(neighbor)
                components.append(comp)
                comp_count += 1

        # Minimum operations = number of components - 1
        result_ops = [str(comp_count - 1)]

        if comp_count > 1:
            # Connect all components to the first one
