    m = int(lines[0])

    def is_valid_set(a, b, set_num):
        """Check if set score a:b is valid for set_num"""
        if a > 200 or b > 200:
            return False
        if a == 0 and b == 0:
            return False

        if set_num <= 4:
            if a > b:
                return a >= 25 and (a - b >= 2)
            elif b > a:
                return b >= 25 and (b - a >= 2)
        else:
            # Set 5
            if a > b:
                return a >= 15 and (a - b >= 2)
            elif b > a:
                return b >= 15 and (b - a >= 2)
        return False

    def solve(a_total, b_total):
        """Find best match outcome for given totals"""
        scenarios = [(3, 0), (3, 1), (3, 2)]
        best_result = None

        # Track best (A_wins, B_wins) pair, preferring more A wins
        best_pair = None

        for a_wins, b_wins in scenarios:
            total_sets = a_wins + b_wins

            # Backtracking to find valid set scores
            def backtrack(idx, rem_a, rem_b, matches_a, matches_b, path):
                if idx == total_sets:
                    if rem_a == 0 and rem_b == 0 and matches_a == a_wins and matches_b == b_wins:
                        return " ".join(f"{a}:{b}" for a, b in path)
                    return None

                # Search for valid set scores
                for a_score in range(min(rem_a, 35)):
                    for b_score in range(min(rem_b, 35)):
                        if is_valid_set(a_score, b_score, idx + 1):
                            # Check who wins this set
                            if a_score > b_score:
                                result = backtrack(
                                    idx + 1,
                                    rem_a - a_score,
                                    rem_b - b_score,
                                    matches_a + 1,
                                    matches_b,
                                    path + [(a_score, b_score)]
                                )
                                if result:
                                    return result
                            elif b_score > a_score:
                                result = backtrack(
                                    idx + 1,
                                    rem_a - a_score,
                                    rem_b - b_score,
                                    matches_a,
                                    matches_b + 1,
                                    path + [(a_score, b_score)]
                                )
                                if result:
                                    return result
                return None

            score_strs = backtrack(0, a_total, b_total, 0, 0, [])

            # Update best result - prioritize 3:0 over 3:1 over 3:2
            if score_strs is not None:
                if best_pair is None or (a_wins, b_wins) < best_pair:
                    best_pair = (a_wins, b_wins)
                    best_result = f"{a_wins}:{b_wins}\n{score_strs} \n"

        return best_result

    all_results = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        if len(parts) >= 2:
            a, b = int(parts[0]), int(parts[1])
            result = solve(a, b)
            if result:
                all_results.append(result)
            else:
                all_results.append("Impossible\n")

    return ''.join(all_results)

